import { override, action, computed, makeObservable, observable, reaction, runInAction } from 'mobx';
import {
    User as UserProps,
    linkToUntis,
    createIcs,
    Role,
    setRole,
    affectedEventIds as apiAffectedEventIds
} from '../api/user';

import { RootStore } from './stores';
import User from '../models/User';
import _ from 'es-toolkit/compat';
import iStore from './iStore';
import EventGroup from '../models/EventGroup';
import { EndPoint } from './EndPoint';
import Storage, { PersistedData, StorageKey } from './utils/Storage';
import { computedFn } from 'mobx-utils';
import scheduleMicrotask from '../models/helpers/scheduleMicrotask';

type ApiAction = 'linkUserToUntis' | 'createIcs';

export class UserStore extends iStore<UserProps, ApiAction> {
    @observable.ref accessor ApiEndpoint = new EndPoint('users', { authorized: true });

    readonly root: RootStore;
    models = observable<User>([]);

    @observable.ref accessor affectedEventIds = observable.set<string>([]);
    _loadedSemesterIds = new Set<string>();

    constructor(root: RootStore) {
        super();
        this.root = root;

        scheduleMicrotask(() => {
            // attempt to load the previous state of this store from localstorage
            this.rehydrate();
        });
    }

    @action
    rehydrate(_data?: PersistedData) {
        if (this.models.length > 0) {
            return;
        }
        const data = Storage.get('SessionStore', _data);
        if (data?.user) {
            try {
                this.addToStore(data.user);
            } catch (e) {
                console.error(e);
                Storage.remove('SessionStore');
            }
        }
    }

    findByTeacherId = computedFn(function (this: UserStore, id?: number): User | undefined {
        if (id === undefined) {
            return undefined;
        }
        return this.models.find((u) => u.untisId === id);
    });

    matchByNameOrEmail = computedFn(function (this: UserStore, val: string): User | undefined {
        if (!val || val.trim().length === 0) {
            return undefined;
        }
        const lowerVal = val.toLowerCase();
        const foundUser = this.models.find(
            (u) =>
                u.email.toLowerCase() === lowerVal ||
                u.displayName.toLowerCase() === lowerVal ||
                u.fullName.toLowerCase() === lowerVal
        );
        return foundUser;
    });

    createModel(data: UserProps): User {
        return new User(data, this, this.root.untisStore);
    }

    findUserGroup(id: string): EventGroup | undefined {
        return this.root.eventGroupStore.find(id);
    }

    @computed
    get current(): User | undefined {
        return this.models.find((u) => u.id === this.root.sessionStore?.currentUserId);
    }

    @computed
    get currentUsersEvents() {
        return this.root.eventStore.byUser(this.current?.id);
    }

    usersEvents(user: User) {
        return this.root.eventStore.byUser(user.id);
    }

    @action
    linkUserToUntis(user: User, untisId: number | null) {
        return this.withAbortController('linkUserToUntis', (sig) => {
            return linkToUntis(user.id, untisId, sig.signal).then(({ data }) => {
                user.setUntisId(data.untisId);
            });
        });
    }

    @action
    setRole(user: User, role: Role) {
        if (!this.current?.isAdmin) {
            return Promise.reject('Not allowed');
        }
        return this.withAbortController(`save-role-${user.id}`, (sig) => {
            return setRole(user.id, role, sig.signal).then(({ data }) => {
                this.addToStore(data);
            });
        });
    }

    @action
    loadUser(id: string) {
        return this.loadModel(id);
    }

    @action
    createIcs() {
        const { current } = this;
        if (!current) {
            return Promise.reject('No current user');
        }
        return this.withAbortController('createIcs', (sig) => {
            return createIcs(current.id, sig.signal).then(({ data }) => {
                if (this.current?.id === current.id) {
                    this.addToStore(data);
                }
            });
        });
    }

    @computed
    get getAffectedEventIds() {
        if (!this.current) {
            return new Set<string>([]);
        }
        return this.affectedEventIds;
    }

    @action
    loadAffectedEventIds(user?: User, semesterId?: string, force?: boolean) {
        if (!user) {
            return Promise.resolve([]);
        }
        if (semesterId && this._loadedSemesterIds.has(semesterId) && !force) {
            return Promise.resolve([]);
        }
        if (semesterId) {
            this._loadedSemesterIds.add(semesterId);
        }
        return this.withAbortController(`load-affected-events-${user.id}-${semesterId}`, (sig) => {
            return apiAffectedEventIds(user.id, semesterId, sig.signal)
                .then(
                    action(({ data }) => {
                        this.affectedEventIds.replace([...this.getAffectedEventIds, ...data]);
                        return data;
                    })
                )
                .catch((e) => {
                    this._loadedSemesterIds.delete(semesterId || '');
                    return Promise.resolve([]);
                });
        });
    }
}
